WITH recent_suppliers AS (SELECT * FROM suppliers WHERE rating > 3.1), city_summary AS (SELECT city, ROUND((100 * SUM(CASE WHEN city = 'Chiang Mai' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_chiang_mai FROM recent_suppliers GROUP BY city) SELECT * FROM city_summary ORDER BY pct_chiang_mai DESC, city LIMIT 5
